SELECT `id`, 'interface', NULL, `key`, `language`, 'imported', `source_text`, `text`, 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
FROM `translation_entries`
WHERE `scope` = 'interface' AND `origin` = 'manual' AND `id` NOT IN (SELECT `entry_id` FROM `translation_history` WHERE `entry_id` IS NOT NULL);
